use reedline :: Span ; use insta :: assert_debug_snapshot ; use super :: SearchTerm ; impl SearchTerm { pub fn new (line : & str , position : usize) -> Self { if position > line . len () { panic ! ("Position {position} is out of bounds: string '{line}' (length: {})" , line . len ()) ; } Self { line : line . to_string () , position } } # [doc = " Get the search term from the line based on '@' marker or cursor position"] # [doc = ""] # [doc = " If '@' marker is present, returns the word following it."] # [doc = " Otherwise, returns the word at the cursor position."] # [doc = " If no word is found, returns None."] pub fn process (& self) -> Option < TermResult < '_ > > { let safe_position = if self . line . is_char_boundary (self . position) { self . position } else { (0 .. self . position) . rev () . find (| & i | self . line . is_char_boundary (i)) . unwrap_or (0) } ; let prefix = self . line . get (.. safe_position) ? ; let at_pos = prefix . rfind ('@') ? ; let start_pos = at_pos + 1 ; let term = self . line . get (start_pos .. safe_position) ? ; Some (TermResult { span : Span :: new (start_pos , safe_position) , term }) } }